    }

    public static int  gcd(int x, int y){
        int r;
        if(x < y){
            int temp;
            temp = x;
            x = y;
            y = temp;
        }

        while(y > 0){
            r = x % y;
            x = y;
            y = r;
        }
        return x;
    }

}

