			int sum = 0;

			for(int j = 0; j < col; j++){
				sum += table[i][j];
			}

			table[i][col] = sum;

		}

		for(int i = 0; i <= col; i++){

			int sum = 0;

			for(int j = 0; j < row; j++){
				sum += table[j][i];
			}

			table[row][i] = sum;

		}

		for(int i = 0; i <= row; i++){
			for(int j = 0; j <= col; j++){

				System.out.print(table[i][j]);

				if(j != col){
