    Scanner sc = new Scanner(System.in);
    int X = sc.nextInt();
    int N = sc.nextInt();
    HashSet<Integer> set = new HashSet<Integer>();

    for(int i=0; i<N; i++){
      set.add(sc.nextInt());
    }

    int ans = X;
    int min = Integer.MAX_VALUE;
    for(int i = 0; i<=200; i++){
