    static class bit {
        int n;
        long[] bit;
        public bit(int n) {
            this.n=n;
            bit=new long[n+1];
        }
        void add(int ind, int c) {
            for(; ind<=n;ind|=(ind+1)) {
                bit[ind]+=c;
            }
        }
        long sum(int r) {
            long out =0;
            for(;r>=0;r=(r&(r+1))-1) {
                out+=bit[r];
            }
            return out;
        }
        long sum(int r, int l) {
            return sum(r)-sum(l-1);
        }
    }
    static class tup implements Comparable<tup> {
        int a, b;

        tup() {
        }

        ;

        tup(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public int compareTo(tup o2) {
            return a==o2.a?Integer.compare(o2.b,b):Integer.compare(o2.a, a);
        }
    }
