class Solver {
	Scanner sc;
	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ======================================================================
    public void solve() {
    	int N = ni();
    	int[] H = new int[N];
    	boolean f = true;
    	for (int i = 0; i < N; i++) {
			H[i] = ni();
			if(H[i] > 0)	f = false;
		}
    	if(f) {
    		out.println(0);
    		return;
    	}
    	int ans = 0;
    	boolean f2;
    	while(true) {
    		f = true;
    		f2 = false;
    		for (int i = 0; i < N; i++) {
    			if(H[i] > 0) {
    				if(!f2) {
    					ans++;
    					f2 = true;
    				}
        			H[i]--;
        			f = false;
    			} else {
    				f2 = false;
    			}
    		}
    		if(f)	break;
		}
    	out.println(ans);
    }
    // ------------------------------------------
    // 入力
    // ------------------------------------------
    public int ni() {
    	return sc.nextInt();
    }
    public long nl() {
    	return sc.nextLong();
    }
    public String ns() {
    	return sc.next();
    }
    public char[] nc() {
    	return sc.next().toCharArray();
    }
    public int[] ndi(int N) {
    	int[] ans = new int[N];
    	for (int i = 0; i < N; i++) {
			ans[i] = ni();
		}
    	return ans;
    }
    public long[] ndl(int N) {
    	long[] ans = new long[N];
    	for (int i = 0; i < N; i++) {
			ans[i] = nl();
		}
    	return ans;
    }
    public String[] nds(int N) {
    	String[] ans = new String[N];
    	for (int i = 0; i < N; i++) {
			ans[i] = ns();
		}
    	return ans;
    }
    public char[][] ndc(int N) {
    	char[][] ans = new char[N][];
    	for (int i = 0; i < N; i++) {
			ans[i] = nc();
		}
    	return ans;
    }
    public int[][] nddi(int N, int S) {
    	int[][] ans = new int[N][S];
    	for (int i = 0; i < N; i++) {
			for (int j = 0; j < S; j++) {
				ans[i][j] = ni();
			}
		}
    	return ans;
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

public class Main {
	InputStream in = System.in;
	PrintStream out = System.out;

	int next(int[] h, int idx) {
		for (int i = idx; i < h.length; i++) {
			if (h[i] != 0) {
				return i;
			}
		}
		return -1;
	}

	public void _main(String[] args) {
		Scanner sc = new Scanner(in);

		int n = sc.nextInt();
		int[] h = new int[n];
		for (int i = 0; i < n; i++) {
			h[i] = sc.nextInt();
		}

		int ans = 0;
		int idx = 0;
		while (true) {
			idx = next(h, idx);
			if (idx == -1) {
				break;
			}

			while (h[idx] > 0) {
				ans++;
				for (int i = idx; i < n && h[i] > 0; i++) {
					h[i]--;
				}
			}
		}

		out.println(ans);

		sc.close();

	}

	public static void main(String[] args) {
		new Main()._main(args);
	}

}

