import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int a = sc.nextInt();
		int b = sc.nextInt();
		int res = 0;

		for (int i = a; i <= b; i++) {
			if (isPalindromic(i)) {
				res++;
			}
		}
		System.out.println(res);
	}

	private static boolean isPalindromic(int n) {
		int num = n;
		int total = 0;
		while (num != 0) {
			total *= 10;
			total += (num % 10);
			num /= 10;
		}
		return n == total;
	}

    static class FastReader {
	    BufferedReader br;
	    StringTokenizer st;

	    public FastReader() {
	      br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() { 
	      while (st == null || !st.hasMoreElements()) {
	        try {
	          st = new StringTokenizer(br.readLine());
	        } catch (IOException  e) {
	          e.printStackTrace();
	        }
	      }
	      return st.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
	      return Double.parseDouble(next());
	    }

	    String nextLine() {
	      String str = "";
	        try{
	            str = br.readLine();
	        } catch (IOException e) {
	            e.printStackTrace();
	        }
	        return str;
	      }
	  }
}

import java.math.*;
import java.util.*;

public class Main {
    static boolean loop(int a) {
        String str = Integer.toString(a);
        int tmp =0;
        if(str.length()%2==0){
            tmp = str.length()/2;
        }
        else {
            tmp = (str.length()- 1) / 2;
        }
        boolean isLoop = true;
        for (int i = 0; i < tmp; i++) {
            if (str.charAt(i) != str.charAt(str.length() - i - 1)) {
                isLoop = false;
                break;
            }
        }
        return isLoop;
}
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int cnt = 0;
        for (int i = a; i <= b; i++) {
            if (loop(i))
                cnt++;
        }
        System.out.println(cnt);
    }
}

