    		        if((1&i>>j) == 1) {a*=list.get(j); b /= list.get(j);}
    		    }
    		    if(min > Math.max(String.valueOf(a).length(), String.valueOf(b).length())) min = Math.max(String.valueOf(a).length(), String.valueOf(b).length());
