		for(int i=0;i<N;i++) {
			S[i] = scanner.next();
			if(map.get(S[i])==null) {
				map.put(S[i], S[i]);
			}
			else {
				map.put(S[i]+i, S[i]);
			}
		}
		L=L+1;
		for(String s:map.values()) {
			System.out.print(s);
		}
		System.out.println();
		scanner.close();
	}

}
